css:
:root {
    --bg: #07111e;
    --bg-2: #0b1a2d;
    --card: #0f2038;
    --card-2: #12233d;
    --line: #22385a;
    --text: #e8eef8;
    --text-dim: #c7d6ec;
    --text-faint: #9cb0cf;
    --accent: #7c9eff;
    --accent-2: #5fd0c4;
    --warn: #f2c14e;
    --sidebar-w: 300px;
}
* {
    box-sizing: border-box;
}
html,
body {
    margin: 0;
    padding: 0;
    overflow-x: hidden;
}
html {
    scroll-behavior: smooth;
}
body {
    background: var(--bg);
    color: var(--text);
    font-family:
        'Noto Sans JP',
        -apple-system,
        BlinkMacSystemFont,
        'Hiragino Kaku Gothic ProN',
        'Yu Gothic',
        Meiryo,
        sans-serif;
    font-size: 16px;
    line-height: 1.85;
    -webkit-font-smoothing: antialiased;
}
a {
    color: var(--accent);
    text-decoration: none;
    overflow-wrap: anywhere;
}
a:hover {
    text-decoration: underline;
}
.layout {
    display: block;
}
.sidebar {
    position: fixed;
    left: 0;
    top: 0;
    bottom: 0;
    width: var(--sidebar-w);
    background: #050d18;
    border-right: 1px solid var(--line);
    overflow-y: auto;
    padding: 22px 16px 40px;
    z-index: 50;
}
.sidebar .brand {
    font-size: 12px;
    letter-spacing: 0.08em;
    color: var(--accent);
    font-weight: 700;
    margin-bottom: 4px;
}
.sidebar .brand-title {
    font-size: 14px;
    font-weight: 700;
    color: var(--text);
    margin-bottom: 18px;
    line-height: 1.5;
}
.sidebar ul {
    list-style: none;
    margin: 0;
    padding: 0;
}
.sidebar > nav > ul > li {
    margin-bottom: 2px;
}
.sidebar a {
    display: block;
    color: var(--text-dim);
    font-size: 13.5px;
    line-height: 1.5;
    padding: 6px 10px;
    border-left: 2px solid transparent;
    border-radius: 0 6px 6px 0;
}
.sidebar a:hover {
    background: #0c1c31;
    text-decoration: none;
    color: #fff;
}
.sidebar a.active {
    color: #fff;
    background: #11284a;
    border-left-color: var(--accent);
}
.sidebar ul.sub {
    margin: 2px 0 6px 10px;
}
.sidebar ul.sub a {
    font-size: 12.5px;
    color: var(--text-faint);
    padding: 4px 10px;
}
.main {
    margin-left: var(--sidebar-w);
    padding: 0 48px 80px;
}
.nav-toggle {
    display: none;
    position: fixed;
    top: 12px;
    left: 12px;
    z-index: 60;
    background: var(--card-2);
    color: var(--text);
    border: 1px solid var(--line);
    border-radius: 8px;
    padding: 8px 12px;
    font: inherit;
    font-size: 14px;
    cursor: pointer;
}
/* hero */
.hero {
    position: relative;
    padding: 56px 0 30px;
    border-bottom: 1px solid var(--line);
    margin-bottom: 12px;
    overflow: hidden;
}
.hero::before {
    content: '';
    position: absolute;
    right: -120px;
    top: -160px;
    width: 520px;
    height: 520px;
    background: radial-gradient(circle, rgba(124, 158, 255, 0.22), transparent 65%);
    pointer-events: none;
}
.eyebrow {
    display: inline-block;
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 0.06em;
    color: var(--accent);
    background: rgba(124, 158, 255, 0.12);
    border: 1px solid rgba(124, 158, 255, 0.35);
    padding: 4px 14px;
    border-radius: 999px;
    margin-bottom: 16px;
}
.hero-title {
    font-size: 28px;
    font-weight: 800;
    color: #fff;
    line-height: 1.4;
    margin: 0 0 8px;
}
.hero-sub {
    color: var(--text-dim);
    font-size: 16px;
    margin: 0 0 24px;
}
.hero-meta {
    display: flex;
    flex-wrap: wrap;
    gap: 0;
    margin: 0;
}
.hero-meta .m {
    padding: 2px 24px 2px 0;
    margin-right: 24px;
    border-right: 1px solid var(--line);
}
.hero-meta .m:last-child {
    border-right: none;
}
.hero-meta .k {
    display: block;
    font-size: 11px;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--text-faint);
}
.hero-meta .v {
    display: block;
    font-size: 14.5px;
    color: var(--text);
}
/* content */
.sec {
    padding-top: 8px;
}
.main h2 {
    font-size: 23px;
    font-weight: 800;
    color: #fff;
    margin: 48px 0 16px;
    padding-bottom: 10px;
    border-bottom: 1px solid var(--line);
    scroll-margin-top: 16px;
}
.main h3 {
    font-size: 18.5px;
    font-weight: 700;
    color: #dfe9ff;
    margin: 34px 0 12px;
    scroll-margin-top: 16px;
}
.main h4 {
    font-size: 16.5px;
    font-weight: 700;
    color: var(--accent-2);
    margin: 26px 0 10px;
}
.main p {
    margin: 0 0 14px;
    color: var(--text-dim);
}
.main strong {
    color: #fff;
    font-weight: 700;
}
.main ul,
.main ol {
    margin: 0 0 14px;
    padding-left: 1.6em;
    color: var(--text-dim);
}
.main li {
    margin: 4px 0;
}
.main code {
    font-family: 'JetBrains Mono', ui-monospace, monospace;
    font-size: 0.9em;
    background: #12233d;
    padding: 2px 6px;
    border-radius: 5px;
    overflow-wrap: anywhere;
}
.main em {
    color: var(--text-dim);
}
.table-scroll {
    overflow-x: auto;
    margin: 16px 0 22px;
    border: 1px solid var(--line);
    border-radius: 10px;
    background: var(--bg-2);
}
table {
    border-collapse: collapse;
    width: 100%;
    font-size: 14.5px;
    line-height: 1.65;
}
th,
td {
    padding: 10px 14px;
    border-bottom: 1px solid var(--line);
    text-align: left;
    vertical-align: top;
    color: var(--text-dim);
}
th {
    background: #112440;
    color: #fff;
    font-weight: 700;
    white-space: nowrap;
    position: sticky;
    top: 0;
}
tr:last-child td {
    border-bottom: none;
}
td:first-child {
    color: var(--text);
}
td a {
    word-break: break-all;
}
/* callouts */
.callout {
    margin: 18px 0 22px;
    padding: 14px 18px 6px;
    border-radius: 10px;
    border: 1px solid var(--line);
    border-left-width: 4px;
    background: var(--card);
}
.callout p {
    color: var(--text-dim);
}
.callout-note {
    border-left-color: var(--accent);
}
.callout-warn {
    border-left-color: var(--warn);
    background: #1b1a0f;
}
.callout-point {
    border-left-color: var(--accent-2);
    background: #0b2229;
}
.callout-tip {
    border-left-color: #b48bff;
    background: #17142b;
}
/* diagrams */
.mermaid-diagram {
    display: block;
    overflow-x: auto;
    border: 1px solid var(--line);
    background: #091729;
    border-radius: 12px;
    padding: 22px 16px;
    margin: 18px 0 24px;
}
.mermaid-diagram svg {
    display: block;
    margin-left: auto;
    margin-right: auto;
    max-width: 100%;
    height: auto;
}
.mermaid-diagram foreignObject {
    overflow: visible;
}
.mermaid-diagram foreignObject div,
.mermaid-diagram foreignObject span,
.mermaid-diagram foreignObject p {
    white-space: normal !important;
}
.mermaid-diagram p {
    color: inherit;
    margin: 0;
}
.page-footer {
    margin-top: 60px;
    padding-top: 20px;
    border-top: 1px solid var(--line);
    color: var(--text-faint);
    font-size: 13px;
}
@media (max-width: 960px) {
    .sidebar {
        transform: translateX(-100%);
        transition: transform 0.2s;
    }
    .sidebar.open {
        transform: none;
        box-shadow: 0 0 40px rgba(0, 0, 0, 0.6);
    }
    .main {
        margin-left: 0;
        padding: 0 18px 60px;
    }
    .nav-toggle {
        display: block;
    }
    .mermaid-diagram svg {
        max-width: none;
    }
    .hero {
        padding-top: 64px;
    }
    .hero-meta .m {
        border-right: none;
        border-bottom: 1px solid var(--line);
        padding: 8px 0;
        margin: 0;
        width: 100%;
    }
    .hero-meta .m:last-child {
        border-bottom: none;
    }
    .hero-title {
        font-size: 23px;
    }
}
